INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c3333333-3333-3333-3333-333333333333', 'Gancho Cosedora Industrial x1000 23-14', 'gancho-cosedora-industrial-x1000-23-14-1675', 'Gancho Cosedora Industrial 23-14 - Caja de 1000 Unidades Ganchos Cosedores Industriales 23-14 de Alta Calidad para Uso Profesional Los Ganchos Cosedora Industrial 23-14 son perfectos para aplicaciones de alto rendimiento en cosedoras industriales. Con una caja que incluye 1000 unidades, estos ganchos están diseñados para proporcionar una sujeción fuerte y duradera en entornos de producción intensivos. Su estructura robusta y resistente asegura un rendimiento confiable y una excelente durabilidad, siendo ideales para talleres, fábricas y otros entornos industriales que requieren eficiencia y calidad en sus operaciones de costura.', 4864.00, 20, 43, true, false, 'https://www.abastece.co/abastece/images/1675.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Cosedora MAE 26/6 Galvanizado x5000', 'gancho-cosedora-mae-266-galvanizado-x5000-71199', 'Ganchos para Cosedora 26/6 Galvanizados - Caja x 5000 Unidades MAE ¡Resistencia y perforación impecable para tus archivos diarios! Los Ganchos para Cosedora MAE (Referencia 26/6) son el estándar de calidad y rendimiento para cualquier entorno de oficina, hogar o papelería. Fabricados con acero galvanizado de alta resistencia, estos ganchos están diseñados para resistir la oxidación y ofrecer una perforación limpia y sin dobleces accidentales. Su tamaño 26/6 es compatible con la gran mayoría de cosedoras estándar de escritorio, permitiendo grapar de 2 a 20 hojas de papel Bond con total seguridad. La presentación en caja de 5000 unidades garantiza un suministro duradero para tareas de alto volumen. Cada tira de ganchos cuenta con un acabado de precisión en las puntas para reducir el esfuerzo al engrapar y evitar atascos en el mecanismo de la cosedora. Es la elección confiable para mantener tus documentos organizados, firmes y con una presentación profesional en todo momento.', 2167.00, 20, 23, true, false, 'https://www.abastece.co/abastece/images/71199.jpg'),
('c3333333-3333-3333-3333-333333333333', 'gancho expediente metalico  No. 8 cajita x 100u.', 'gancho-expediente-metalico-no-8-cajita-x-100u-0254', 'Gancho Expediente Metalico No. 8 Cajita x 100u. Organizacion y Seguridad para Archivos y Documentos El Gancho Expediente Metalico No. 8 es la solucion perfecta para mantener tus documentos organizados y asegurados en cualquier archivo o expediente. Fabricado en metal de alta calidad, este gancho ofrece una resistencia y durabilidad excepcionales, asegurando que tus documentos permanezcan sujetos de manera segura. El tamaño No. 8 es ideal para archivos de tamaño estandar, permitiendo que puedas clasificar y almacenar grandes cantidades de papeles de forma eficiente. Cada cajita contiene 100 unidades, lo que te proporciona suficiente material para varios proyectos de organizacion de documentos. Es una opcion esencial para oficinas, escuelas y otros entornos donde la organizacion de archivos es clave.', 9074.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/0254.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Expediente Metalico No. 6 Cajita X100u.', 'gancho-expediente-metalico-no-6-cajita-x100u-0823', 'Gancho Expediente Metálico No. 6 Cajita x100u. Organización y Durabilidad para Archivar Documentos Los Ganchos Expediente Metálicos No. 6 en presentación de cajita con 100 unidades son perfectos para mantener tus documentos organizados y bien sujetos. Fabricados con metal de alta calidad, estos ganchos ofrecen una resistencia superior, ideal para su uso en oficinas, archivos y espacios laborales. Su diseño permite sujetar hojas, carpetas o expedientes de manera segura y ordenada, optimizando el almacenamiento y evitando el desorden. Su tamaño No. 6 es perfecto para archivos de tamaño estándar. Una solución económica y práctica para mantener la documentación bien organizada.', 8882.00, 20, 22, true, false, 'https://www.abastece.co/abastece/images/0823.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Expediente Metalico No. 7 Cajita X 100u.', 'gancho-expediente-metalico-no-7-cajita-x-100u-3142', 'Gancho Expediente Metálico No. 7 - Caja x 100 unidades ¡Sujeción máxima y seguridad para la organización de expedientes voluminosos! El Gancho para Expediente No. 7 es la solución técnica definitiva para la foliación y aseguramiento de documentos en carpetas de archivo. Fabricado en acero con recubrimiento galvanizado de alta calidad, este gancho ofrece una resistencia superior a la flexión y una protección eficaz contra la oxidación, evitando manchas en el papel a largo plazo. Su diseño de bordes redondeados y acabado liso permite una manipulación segura, mientras que su longitud extendida facilita el legajado de una gran cantidad de folios manteniendo la unidad del archivo. Es el insumo indispensable para gestión de historias clínicas, archivos notariales, expedientes jurídicos y oficinas de recursos humanos.', 9072.00, 20, 43, true, false, 'https://www.abastece.co/abastece/images/3142.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Legajador Beba Plastico 18cm x100 Q-9995-100', 'gancho-legajador-beba-plastico-18cm-x100-q-9995-100-9425', 'Gancho Legajador Plástico 18 Cms Beba - Paquete por 100 unidades La mejor solución para organizar tus documentos El Gancho Legajador Plástico de 18 cm es ideal para archivar y asegurar documentos de manera práctica y eficiente. Su diseño resistente garantiza durabilidad y un excelente desempeño en oficinas, escuelas y archivos.', 135240.00, 20, 21, true, false, 'https://www.abastece.co/abastece/images/9425.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Legajador Beba Plastico Paq.x 100u. 12cm 9998-100', 'gancho-legajador-beba-plastico-paqx-100u-12cm-9998-100-71636', 'Gancho Legajador Plástico 12cm Beba x100 Ref: Q9998-100 Organiza y asegura tus documentos con facilidad Los ganchos legajadores plásticos Beba de 12 cm son perfectos para mantener tus documentos organizados de manera eficiente. Con una capacidad para sujetar grandes cantidades de papeles, cada paquete contiene 100 unidades, lo que los hace ideales para oficinas, empresas o proyectos a gran escala. Su diseño resistente asegura que tus documentos se mantengan bien sujetos y en orden.', 35308.00, 20, 36, true, false, 'https://www.abastece.co/abastece/images/71636.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Legajador Metal/Plastico Institucional Triton Caja X 20u.', 'gancho-legajador-metalplastico-institucional-triton-caja-x-20u-75632', 'Gancho Legajador Institucional Triton (Metal/Plástico) - Caja x 20 unidades ¡Seguridad híbrida y durabilidad excepcional para la foliación de archivos críticos! El Gancho Legajador Institucional Triton es un componente de alta ingeniería diseñado para la sujeción definitiva de documentos en carpetas y archivos de gestión. Su estructura combina la flexibilidad del polímero de alta densidad con la rigidez de un alma metálica reforzada, ofreciendo lo mejor de ambos materiales: una manipulación suave que evita cortes en las manos y una fuerza de cierre que mantiene los folios perfectamente alineados. Su acabado está optimizado para resistir la fricción constante y proteger el papel contra manchas de óxido. Es el insumo indispensable para instituciones educativas, archivos gubernamentales, centros de documentación y administración de propiedad horizontal.', 2129.00, 20, 15, true, false, 'https://www.abastece.co/abastece/images/75632.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Legajador Plastico Tipo Expediente Paquete Por 20 Rank', 'gancho-legajador-plastico-tipo-expediente-paquete-por-20-rank-5842', 'Gancho Legajador Plastico Tipo Expediente - Paquete por 20 Rank Organizacion y sujecion segura para tus documentos El gancho legajador plastico tipo expediente de Rank es ideal para mantener tus documentos bien organizados y sujetos de manera firme. Su material resistente garantiza durabilidad y facilidad de uso en oficinas, colegios y archivos. ¡Optimiza el almacenamiento de documentos con un sistema practico y eficiente!', 3751.00, 20, 35, true, false, 'https://www.abastece.co/abastece/images/5842.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Legajador Plastico Transparente Paq. X 20 Rank', 'gancho-legajador-plastico-transparente-paq-x-20-rank-5652', 'Gancho Legajador Plástico Transparente Paquete x 20 Rank 201 ¡Asegure una organización impecable, visible y profesional para sus archivos y documentos! Optimice la gestión documental y el archivo de su organización con este sistema de sujeción de alta resistencia. El acabado limpio de este gancho legajador plástico transparente paquete x 20 Rank 201 facilita la estandarización de procesos administrativos y de auditoría, permitiendo indexar, foliar y revisar carpetas sin obstruir la lectura de los textos ni los bordes de las hojas. Su fabricación en polímero flexible de alta durabilidad asegura la continuidad operativa en oficinas, notarías y centros de documentación, garantizando un mecanismo de doble pinza que no se deforma, no se quiebra con el uso constante y evita el deterioro del papel por óxido o fricción. Incorpore este paquete hoy mismo para mejorar la eficiencia logística de su inventario de papelería con un suministro compacto y de alto rendimiento, potenciando el bienestar del equipo al simplificar las tareas de archivo y asegurar un acceso rápido, seguro y ordenado a la información crítica del negocio.', 1836.00, 20, 53, true, false, 'https://www.abastece.co/abastece/images/5652.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Legajador Plastico Transparente Paq. X 20 Rank Ref 300', 'gancho-legajador-plastico-transparente-paq-x-20-rank-ref-300-77356', 'Gancho Legajador Plástico Transparente Paquete por 20 Unidades – Rank Ref 300 ¡Organiza y asegura tus documentos con la máxima limpieza y durabilidad! Mantén tus archivos corporativos impecables y en perfecto orden con este sistema de sujeción de alta resistencia. Su fabricación en plástico cristalino y su presentación en paquete por 20 unidades de la marca Rank Referencia 300 facilitan la estandarización de procesos de archivo central, auditorías y gestión documental, evitando las manchas de óxido que dañan el papel. Su mecanismo flexible y pestañas de ajuste seguro aseguran la continuidad operativa durante las consultas diarias, permitiendo hojear expedientes pesados sin romper las perforaciones. Adquiérelo hoy para optimizar la eficiencia logística de tu inventario de papelería, reforzando el bienestar del equipo al facilitar un archivo rápido, seguro y con una presentación impecable.', 1641.00, 20, 15, true, false, 'https://www.abastece.co/abastece/images/77356.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Legajador Plastico Transparente Paq.x20u.', 'gancho-legajador-plastico-transparente-paqx20u-71328', 'Gancho Legajador Plastico Transparente Paquete por 20 Organiza tus documentos con facilidad y estilo El Gancho Legajador Plastico Transparente es la herramienta perfecta para mantener tus documentos organizados y accesibles. Este paquete incluye 20 ganchos legajadores de alta calidad, ideales para uso en oficinas, archivos y presentaciones. Gracias a su diseño practico y transparente, puedes ver rapidamente el contenido de tus carpetas mientras mantienes todo ordenado. Resistente y duradero, es una opcion ideal para organizar documentos de manera eficiente.', 1786.00, 20, 50, true, false, 'https://www.abastece.co/abastece/images/71328.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho metalico para carnet', 'gancho-metalico-para-carnet-0715', 'Gancho Metálico para Carnet Una solución práctica y resistente para tu identificación El Gancho Metálico para Carnet es la opción ideal para mantener tu carnet de identificación seguro y accesible. Fabricado en metal resistente, este gancho asegura una sujeción firme y duradera, permitiéndote llevar tu carnet de forma cómoda durante todo el día. Su diseño práctico es perfecto para ser usado en oficinas, eventos, o cualquier lugar donde se necesite portar un carnet de manera visible. ¡Mantén tus documentos importantes siempre a mano con el gancho metálico para carnet!', 335.00, 20, 43, true, false, 'https://www.abastece.co/abastece/images/0715.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Plastiflecha Manual X5000u.', 'gancho-plastiflecha-manual-x5000u-75357', 'Gancho Plastiflecha Manual - Caja x 5000 unidades ¡Eficiencia y precisión en el etiquetado para la industria textil y comercial! El Gancho Plastiflecha (Fastener) es el estándar técnico para la fijación de etiquetas colgantes en prendas de vestir, calzado y diversos artículos textiles. Fabricado en polipropileno de alta densidad, este insumo ofrece una resistencia superior al desprendimiento accidental, garantizando que la información de precio, marca y talla permanezca asegurada durante toda la cadena logística. Su diseño es totalmente compatible con la mayoría de pistolas etiquetadoras manuales del mercado, permitiendo una aplicación fluida y sin atascos. Con una presentación de 5000 unidades, es la solución más rentable para procesos de etiquetado masivo. Es el insumo indispensable para confecciones, grandes superficies, boutiques y bodegas de distribución.', 29153.00, 20, 38, true, false, 'https://www.abastece.co/abastece/images/75357.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Plastiflecha Trabajo Pesado TG X 5000 Und', 'gancho-plastiflecha-trabajo-pesado-tg-x-5000-und-75981', 'Gancho Plastiflecha Trabajo Pesado (TG) - Caja x 5000 unidades ¡Máxima resistencia y seguridad para el etiquetado de materiales densos y exigentes! El Gancho Plastiflecha para Trabajo Pesado (TG) es el insumo técnico diseñado específicamente para aplicaciones que requieren una fuerza de sujeción superior y una durabilidad excepcional. Fabricado con un polímero reforzado de alta tenacidad, este fastener está optimizado para resistir la tensión en materiales de gran calibre como denim pesado, cueros, lonas, alfombras y textiles industriales. Su diseño es compatible con pistolas etiquetadoras de aguja gruesa, garantizando una inserción firme y un anclaje que previene el desprendimiento de etiquetas durante procesos de lavado industrial, transporte o manipulación ruda. Con una presentación de 5000 unidades, asegura una operación continua y eficiente. Es el insumo indispensable para marroquinerías, fábricas de jeans, industrias de calzado y centros de distribución logística a gran escala.', 14330.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/75981.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Velobind Paquete x 25u.', 'gancho-velobind-paquete-x-25u-0790', 'Gancho Velobin x 25: Solucion Practica para Encuadernacion Union Segura y Duradera para tus Documentos Son la opcion perfecta para la encuadernacion de tus documentos. Con estos ganchos, podras unir y asegurar tus paginas de forma rapida y sencilla. Cada paquete contiene 25 ganchos. Su diseoo resistente y confiable garantiza una union segura y duradera. Ya sea que necesites encuadernar informes, manuales, catalogos u otros documentos, los Ganchos Velobin son una solucion practica y eficiente.', 9982.00, 20, 45, true, false, 'https://www.abastece.co/abastece/images/0790.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Yoyo Carnet Americano Rojo', 'gancho-yoyo-carnet-americano-rojo-3030', 'Gancho Yoyo para Carnet Tipo Americano - Color Rojo ¡Acceso rápido, seguridad y visibilidad para su identificación corporativa! El Gancho Yoyo Porta Carnet Tipo Americano es el accesorio ergonómico esencial para la gestión de control de acceso y seguridad de personal. Fabricado con una carcasa de ABS de alta resistencia en un vibrante acabado color rojo, este dispositivo cuenta con un mecanismo retráctil de nailon reforzado que permite extender la identificación hasta 60 cm para acercarla a lectores biométricos o de proximidad sin necesidad de desprenderla. Su clip metálico posterior asegura un agarre firme en solapas, bolsillos o cinturones, mientras que su correa de vinilo transparente con broche de presión es compatible con cualquier portacarnet estándar. Es la solución ideal para brigadistas, personal de seguridad, servicios de emergencia, eventos corporativos y sectores administrativos que requieren una identificación visual inmediata y funcional.', 1623.00, 20, 31, true, false, 'https://www.abastece.co/abastece/images/3030.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Yoyo Carnet Negro X10 Unidades', 'gancho-yoyo-carnet-negro-x10-unidades-4121', 'Gancho Yoyo Carnet Negro X10 Unidades ¡Optimice el control de acceso y la identificación de su personal con un sistema retráctil de alta durabilidad! Maximice la seguridad y agilice la identificación visual dentro de sus instalaciones con este sistema de sujeción corporativa de alto rendimiento. El diseño sobrio y funcional de este gancho yoyo carnet negro x10 unidades facilita la estandarización de procesos de control de acceso y seguridad industrial en oficinas, plantas de producción y centros de distribución, permitiendo que cada colaborador porte su identificación de manera visible y uniforme. Su mecanismo retráctil reforzado de nylon y gancho de fijación aseguran la continuidad operativa en los puntos de marcación y torniquetes, garantizando una extensión suave y un retorno automático duradero que soporta el uso diario intensivo sin atascos. Adquiera este paquete hoy mismo para mejorar la eficiencia logística de sus suministros de oficina y dotación con un accesorio elegante y de alta rotación, potenciando el bienestar del equipo al brindar comodidad y libertad de movimiento, evitando la pérdida o el deterioro de las tarjetas de proximidad y documentos de identidad empresarial.', 1738.00, 20, 21, true, false, 'https://www.abastece.co/abastece/images/4121.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Yoyo Carnet Verde Unidad', 'gancho-yoyo-carnet-verde-unidad-77650', 'Gancho Yoyo Carnet Verde Unidad ¡Asegure la identificación visible del personal, optimice el control de acceso y garantice la seguridad en las instalaciones! Garantice la portabilidad, acceso rápido a lectores de proximidad y presentación impecable de las credenciales de identificación de sus colaboradores, contratistas y visitantes en sedes corporativas o eventos. El uso del gancho yoyo carnet verde unidad (con mecanismo retráctil de alta resistencia y clip metálico de fijación) facilita la estandarización de procesos en la gestión de control de acceso, carnetización empresarial e identificación de personal, unificando el catálogo de accesorios corporativos para sus departamentos de seguridad, recursos humanos, servicios generales y recepción. Su piola extensible asegura la continuidad operativa en puntos de marcación, torniquetes y validación de seguridad, permitiendo estirar la credencial y retornarla automáticamente a su posición sin necesidad de desengancharla de la prenda de vestir. Incorpore este insumo a sus compras de dotación institucional para elevar la eficiencia logística en la entrega de suministros de oficina, impulsando el bienestar del equipo al brindar accesorios funcionales, duraderos y alineados con la identidad visual o corporativa de la organización.', 596.00, 20, 31, true, false, 'https://www.abastece.co/abastece/images/77650.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Yoyo Para Carnet Azul X10 Unidades.', 'gancho-yoyo-para-carnet-azul-x10-unidades-3962', 'Gancho Yoyo Para Carnet Azul X10 Unidades.', 669378.00, 20, 41, true, false, 'https://www.abastece.co/abastece/images/3962.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Yoyo Para Carnet Blanco X10 Unidades.', 'gancho-yoyo-para-carnet-blanco-x10-unidades-77753', 'Gancho Yoyo Para Carnet Blanco X10 Unidades. ¡Mecanismo retráctil fluido, diseño elegante y sujeción segura para la identificación de su personal! Optimice la portabilidad y el acceso a carnets o escarapelas de identificación con el paquete de gancho yoyo retráctil en color blanco por 10 unidades. Diseñado con un cordón de alta resistencia y un sistema de resorte duradero, este accesorio permite extender la escarapela sin necesidad de desengancharla de la prenda, facilitando la lectura en sistemas de control de acceso magnéticos o biométricos. Su broche de presión transparente asegura firmemente la funda o tarjeta, mientras que el clip metálico posterior se fija con estabilidad a bolsillos, solapas o cinturones. Es la solución ideal para empresas, eventos, ferias, colegios y hospitales que buscan una presentación limpia, uniforme y profesional de su personal. ¡Adquiera su paquete hoy y mantenga sus credenciales siempre a la mano!', 5958.00, 20, 16, true, false, 'https://www.abastece.co/abastece/images/77753.jpg'),
